style:
/* Cavalry for Mac: Cerulean palette and ledger typography (20/29 desktop styles). */
:root {
  color-scheme: light;
  --bg: #edf4ff;
  --panel: #fffefa;
  --ink: #111111;
  --muted: #666666;
  --line: #b9bdc5;
  --accent: #1a3fe9;
  --accent-hover: #1233ca;
  --mono: 'IBM Plex Mono', 'SFMono-Regular', 'SF Mono', Consolas, monospace;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: var(--ink);
  background: var(--bg);
  font-synthesis: none;
  -webkit-font-smoothing: antialiased;
}
* {
  box-sizing: border-box;
}
[hidden] {
  display: none !important;
}
body {
  margin: 0;
  padding: clamp(20px, 6vh, 64px) 24px;
}
main {
  width: min(100%, 560px);
  margin: 0 auto;
  background: var(--panel);
  border: 2px solid var(--ink);
  border-radius: 8px;
  overflow: hidden;
}
.brand {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 22px 28px;
  border-bottom: 2px solid var(--ink);
}
.mark {
  display: block;
  width: 52px;
  height: 52px;
  border-radius: 4px;
}
.brand strong {
  display: block;
  font: 700 23px/1.2 var(--mono);
  letter-spacing: -1px;
}
.brand small {
  display: block;
  margin-top: 6px;
  color: var(--muted);
  font: 600 10px/1.3 var(--mono);
  letter-spacing: 1.5px;
  text-transform: uppercase;
}
.content {
  padding: 30px 28px 28px;
}
.eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 0 22px;
  color: var(--accent);
  font: 700 11px/1.4 var(--mono);
  letter-spacing: 1px;
  text-transform: uppercase;
}
.eyebrow::before {
  content: '';
  width: 22px;
  height: 3px;
  background: currentColor;
}
h1 {
  font-size: clamp(28px, 6vw, 38px);
  font-weight: 750;
  line-height: 1.12;
  letter-spacing: -1.25px;
  margin: 0 0 18px;
  max-width: 400px;
}
p {
  line-height: 1.6;
}
.description {
  color: #30343b;
  font-size: 15px;
  margin: 0 0 22px;
}
.account-note {
  padding: 13px 15px;
  border: 1px solid var(--line);
  border-left: 3px solid var(--accent);
  background: #f3f3f0;
  font-size: 13px;
  line-height: 1.5;
  margin: 0 0 24px;
}
.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
button {
  min-height: 46px;
  padding: 13px 17px;
  border: 2px solid var(--accent);
  border-radius: 4px;
  color: #ffffff;
  background: var(--accent);
  font: 700 12px/1.3 var(--mono);
  letter-spacing: 0.25px;
  text-transform: uppercase;
  cursor: pointer;
}
button:hover:not(:disabled) {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}
button.secondary {
  color: var(--ink);
  background: transparent;
  border-color: var(--line);
}
button.secondary:hover:not(:disabled) {
  background: #f3f3f0;
  border-color: var(--ink);
}
button:disabled {
  cursor: default;
  opacity: 0.55;
}
button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 4px;
}
#status {
  color: #30343b;
  font-size: 13px;
  margin: 20px 0 0;
  min-height: 21px;
}
.footnote {
  color: var(--muted);
  font-size: 12px;
  margin: 0;
  padding: 17px 28px;
  border-top: 1px solid var(--line);
  background: #f3f3f0;
}
#diagnostics {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  color: var(--muted);
  font: 11px/1.5 var(--mono);
}
main[data-state='complete'] .eyebrow {
  color: #19804f;
}
main[data-state='complete'] #status {
  color: #19804f;
  padding: 13px 15px;
  border: 1px solid #9abca9;
  background: #edf6ef;
}
@media (max-width: 420px) {
  body {
    padding: 16px;
  }
  .brand {
    padding: 20px;
  }
  .content {
    padding: 24px 20px;
  }
  .footnote {
    padding: 16px 20px;
  }
  .actions {
    flex-direction: column;
  }
  button {
    width: 100%;
  }
}
